/// <summary>
/// parm method for Item number
/// </summary>
/// <param name = "_itemId">Item number</param>
/// <returns>Item number</returns>
[DataMemberAttribute('ItemNumber')]
public ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}
